import type { Product, ProductBadge, ProductImage, ProductVariant } from "@/types";
import { COLORS, type ColorKey } from "./colors";

/**
 * DEMONSTRATION CATALOGUE. Prices, stock and ratings are sample values for
 * building the UI; they are not real inventory. Images are placeholder SVGs
 * generated by `scripts/generate-placeholders.mjs`.
 */

const SHIRT_SIZES = ["S", "M", "L", "XL", "XXL"];
const PANT_SIZES = ["30", "32", "34", "36", "38"];
const SHOE_SIZES = ["39", "40", "41", "42", "43", "44"];
const BELT_SIZES = ["32", "34", "36", "38"];
const ONE_SIZE = ["One Size"];

interface ProductSeed {
  id: string;
  slug: string;
  name: string;
  style: string;
  category: "shirts" | "pants" | "sneakers" | "belts" | "wallets" | "watches";
  brand: string;
  price: number;
  compareAtPrice?: number;
  colors: ColorKey[];
  shortDescription: string;
  description: string;
  details: string[];
  material?: string;
  badges?: ProductBadge[];
  isNewArrival?: boolean;
  isFeatured?: boolean;
  isBestSeller?: boolean;
  rating: [number, number];
  createdAt: string;
  tags?: string[];
}

const SIZE_BY_CATEGORY: Record<ProductSeed["category"], string[]> = {
  shirts: SHIRT_SIZES,
  pants: PANT_SIZES,
  sneakers: SHOE_SIZES,
  belts: BELT_SIZES,
  wallets: ONE_SIZE,
  watches: ONE_SIZE,
};

const SIZE_GUIDE_BY_CATEGORY: Partial<Record<ProductSeed["category"], string>> = {
  shirts: "tops",
  pants: "bottoms",
  sneakers: "shoes",
  belts: "belts",
};

const CARE_BY_CATEGORY: Record<ProductSeed["category"], string[]> = {
  shirts: ["Machine wash cold with similar colours", "Do not bleach", "Warm iron on reverse"],
  pants: ["Machine wash cold, inside out", "Line dry in shade", "Warm iron"],
  sneakers: ["Wipe clean with a damp cloth", "Air dry away from direct heat"],
  belts: ["Wipe with a dry cloth", "Condition leather occasionally"],
  wallets: ["Keep away from moisture", "Condition leather occasionally"],
  watches: ["Splash resistant — avoid swimming", "Wipe with a soft dry cloth"],
};

const image = (style: string, color: ColorKey, view: "front" | "detail" | "alt", name: string): ProductImage => ({
  src: `/images/products/${style}-${color}-${view}.svg`,
  alt: `${name} in ${COLORS[color].name} — ${view === "front" ? "front view" : view === "detail" ? "detail view" : "alternate view"}`,
  width: 800,
  height: 1000,
});

/** Deterministic pseudo-random stock so the demo is stable across renders. */
const stockFor = (seed: string) => {
  let h = 0;
  for (const ch of seed) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const n = h % 17;
  return n < 2 ? 0 : n;
};

function build(seed: ProductSeed): Product {
  const sizes = SIZE_BY_CATEGORY[seed.category];
  const variants: ProductVariant[] = seed.colors.flatMap((color) =>
    sizes.map((size) => ({
      id: `${seed.id}-${color}-${size}`.toLowerCase().replace(/\s+/g, ""),
      sku: `AA-${seed.id.toUpperCase()}-${color.slice(0, 3).toUpperCase()}-${size.replace(/\s+/g, "")}`,
      colorId: color,
      size,
      stock: stockFor(`${seed.id}${color}${size}`),
    })),
  );
  const imagesByColor = Object.fromEntries(
    seed.colors.map((color) => [
      color,
      (["front", "alt", "detail"] as const).map((view) => image(seed.style, color, view, seed.name)),
    ]),
  );
  const first = seed.colors[0] as ColorKey;
  return {
    id: seed.id,
    slug: seed.slug,
    name: seed.name,
    shortDescription: seed.shortDescription,
    description: seed.description,
    categoryId: `cat-${seed.category}`,
    brandId: seed.brand,
    price: seed.price,
    compareAtPrice: seed.compareAtPrice,
    colors: seed.colors.map((c) => COLORS[c]),
    sizes,
    variants,
    imagesByColor,
    defaultImages: imagesByColor[first] ?? [],
    details: seed.details,
    material: seed.material,
    care: CARE_BY_CATEGORY[seed.category],
    badges: seed.badges ?? [],
    isNewArrival: seed.isNewArrival ?? false,
    isFeatured: seed.isFeatured ?? false,
    isBestSeller: seed.isBestSeller ?? false,
    rating: { average: seed.rating[0], count: seed.rating[1] },
    createdAt: seed.createdAt,
    tags: seed.tags ?? [],
    sizeGuideId: SIZE_GUIDE_BY_CATEGORY[seed.category],
  };
}

